ee:message.ee:set-payload:
					%dw 2.0
output application/java
---
do {
	// Determine buyer and select appropriate file - no fallback
	var buyerName = payload.purchaseOrder.buyer.name
	var historicalDataFile = if (buyerName == "TECHWAVE") 
		"classpath://data/hist-data-techwave.json"
	else if (buyerName == "BrightView Electronics LLC")
		"classpath://data/histo-data-brightview.json"
	else 
		null  // No data loaded for other buyers

	// Only load data if we have a valid file
	var historicalData = if (historicalDataFile != null) 
		readUrl(historicalDataFile, "application/json")
	else 
		[]  // Return empty array if no matching buyer

	// Map the data structure (only if we have data)
	var mappedData = if (historicalData != [])
		historicalData map ((item, index) -> {
			vendorId: item.purchaseOrder.vendor.name,
			amount: item.purchaseOrder.amounts.total,
			poDate: item.purchaseOrder.purchaseOrderDate,
			description: (item.purchaseOrder.items[0].description default ""),
			// Include richer data for updated consuming flows
			fullPurchaseOrder: item.purchaseOrder,
			buyer: item.purchaseOrder.buyer,
			vendor: item.purchaseOrder.vendor,
			items: item.purchaseOrder.items,
			amounts: item.purchaseOrder.amounts
		})
	else 
		[]

	// Filter by buyer (updated behavior)
	var buyerFilteredData = mappedData filter ($.buyer.name == payload.buyerId)
	---
	buyerFilteredData
}
